//! The connect kit's "More" list (CONTRACT-connections-2026-11, section 11):
//! `GET /api/v1/connections/catalog`.
//!
//! Everything here is static except one fact per request (does the account
//! have a computer online, which decides `available` for apps):
//!
//! - brains: the key rows the cloud stores (`connections::KEY_ROWS`) minus the voice base rows, each a
//!   `paste` way with its key page.
//! - apps: the committed snapshot `src/services/connections_catalog_apps.json` (inside src/ because scripts/deploy-cloud-api.sh syncs only src, tests and migrations)
//!   (generated by `services/open-connector/scripts/export-directory.ts`)
//!   minus every base row id the clients already draw, so a base row never
//!   shows up twice.
//! - computers, phones, tools, voice, channels: empty (every id is a base row).
//!
//! `q` ranks: name starts with it, then name contains it, then category or
//! blurb contains it; ties by name. `counts` follow `q` but not `group`.
//! The cursor is the offset as a decimal string.

use std::collections::HashSet;
use std::sync::OnceLock;

use chrono::{DateTime, Duration, Utc};
use serde::{Deserialize, Serialize};
use sqlx::PgPool;

use crate::error::ApiError;
use crate::services::connections::{key_page, KEY_ROWS};

pub const VERSION: u32 = 1;

/// The seven groups, in the order an unfiltered page lists them.
pub const GROUPS: [&str; 7] = ["brains", "computers", "phones", "tools", "voice", "apps", "channels"];

pub const DEFAULT_LIMIT: usize = 24;
pub const MAX_LIMIT: usize = 60;
/// `q` is cut to this many characters.
pub const MAX_QUERY_CHARS: usize = 64;

/// Why an app is unavailable with no computer online.
pub const NEEDS_COMPUTER: &str = "Runs on a computer.";

/// The app snapshot (step 2 of the connections-catalog plan).
const SNAPSHOT: &str = include_str!("connections_catalog_apps.json");

/// Ids the clients already draw as base rows (allternit-ai
/// `connect-kit/registry.ts`, ids and `connectorId`s), plus the reserved
/// `catalog`. None of them is ever a catalog entry.
pub const BASE_IDS: &[&str] = &[
    // brains
    "allternit", "claude", "gemini", "copilot", "chatgpt", "grok", "kimi", "api-key", "local", "claude-org",
    // computers, phones
    "cloud-computer", "this-mac", "server", "phone", "android-screen", "phone-control",
    // tools
    "claude-code", "codex", "grok-cli", "kimi-cli", "gemini-cli", "cursor",
    // voice
    "openai-voice", "elevenlabs",
    // apps (row ids and connector ids)
    "gmail", "drive", "google_drive", "slack", "github", "notion",
    // channels
    "telegram", "whatsapp", "discord",
    // reserved
    "catalog",
];

/// Display names of the key rows (allternit-ai `KEY_PROVIDERS`).
fn key_row_name(id: &str) -> &'static str {
    match id {
        "openai-key" => "OpenAI",
        "anthropic-key" => "Anthropic",
        "google-key" => "Google AI Studio",
        "xai-key" => "xAI",
        "together-key" => "Together",
        "fireworks-key" => "Fireworks",
        "deepinfra-key" => "DeepInfra",
        "groq-key" => "Groq",
        "deepseek-key" => "DeepSeek",
        "kimi-key" => "Kimi (Moonshot)",
        "openrouter-key" => "OpenRouter",
        _ => "API",
    }
}

/// One catalog entry, exactly as the contract's JSON.
#[derive(Debug, Clone, PartialEq, Serialize)]
pub struct Entry {
    pub id: String,
    pub group: &'static str,
    pub name: String,
    pub blurb: String,
    pub category: String,
    pub ways: Vec<&'static str>,
    pub runs_on: &'static str,
    pub connector_id: Option<String>,
    pub key_page: Option<&'static str>,
    pub logo: Option<String>,
    pub available: bool,
    pub unavailable_reason: Option<&'static str>,
    pub fallbacks: Vec<&'static str>,
}

/// Per-group totals after `q`.
#[derive(Debug, Clone, Default, PartialEq, Serialize)]
pub struct Counts {
    pub brains: usize,
    pub computers: usize,
    pub phones: usize,
    pub tools: usize,
    pub voice: usize,
    pub apps: usize,
    pub channels: usize,
}

impl Counts {
    fn bump(&mut self, group: &str) {
        match group {
            "brains" => self.brains += 1,
            "computers" => self.computers += 1,
            "phones" => self.phones += 1,
            "tools" => self.tools += 1,
            "voice" => self.voice += 1,
            "apps" => self.apps += 1,
            "channels" => self.channels += 1,
            _ => {}
        }
    }
}

/// The response body.
#[derive(Debug, Clone, PartialEq, Serialize)]
pub struct Page {
    pub version: u32,
    pub group: Option<&'static str>,
    pub q: Option<String>,
    pub total: usize,
    pub next_cursor: Option<String>,
    pub counts: Counts,
    pub entries: Vec<Entry>,
}

/// A parsed, clamped request.
#[derive(Debug, Clone, PartialEq)]
pub struct Query {
    pub group: Option<&'static str>,
    /// Trimmed, lowercased, at most [`MAX_QUERY_CHARS`]; `None` when empty.
    pub q: Option<String>,
    pub limit: usize,
    pub offset: usize,
}

/// A 400 the route answers as `{"error": code}`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum QueryError {
    UnknownGroup,
    BadCursor,
}

impl QueryError {
    pub fn code(self) -> &'static str {
        match self {
            QueryError::UnknownGroup => "unknown_group",
            QueryError::BadCursor => "bad_cursor",
        }
    }
}

/// Parse the raw query values. An empty value counts as absent; a `limit`
/// that is not a number is the default; the cursor must be a decimal offset.
pub fn parse_query(
    group: Option<&str>,
    q: Option<&str>,
    limit: Option<&str>,
    cursor: Option<&str>,
) -> Result<Query, QueryError> {
    let group = match group.map(str::trim).filter(|g| !g.is_empty()) {
        None => None,
        Some(name) => Some(*GROUPS.iter().find(|g| **g == name).ok_or(QueryError::UnknownGroup)?),
    };
    let q = q
        .map(|q| q.trim().to_lowercase().chars().take(MAX_QUERY_CHARS).collect::<String>())
        .map(|q| q.trim().to_string())
        .filter(|q| !q.is_empty());
    let limit = match limit.map(str::trim).filter(|l| !l.is_empty()).and_then(|l| l.parse::<i64>().ok()) {
        None => DEFAULT_LIMIT,
        Some(n) => n.clamp(0, MAX_LIMIT as i64) as usize,
    };
    let offset = match cursor.map(str::trim).filter(|c| !c.is_empty()) {
        None => 0,
        Some(c) if c.bytes().all(|b| b.is_ascii_digit()) => c.parse::<usize>().map_err(|_| QueryError::BadCursor)?,
        Some(_) => return Err(QueryError::BadCursor),
    };
    Ok(Query { group, q, limit, offset })
}

/// Whether the page will hold app entries, i.e. whether the route needs the
/// "computer online" fact at all (`limit=0` and other groups never do).
pub fn needs_computer_fact(query: &Query) -> bool {
    query.limit > 0 && matches!(query.group, None | Some("apps"))
}

/// An entry with its search text, built once.
struct Item {
    entry: Entry,
    group_rank: usize,
    name_lc: String,
    /// Category and blurb, lowercased.
    other_lc: String,
}

#[derive(Deserialize)]
struct Snapshot {
    apps: Vec<SnapshotApp>,
}

#[derive(Deserialize)]
struct SnapshotApp {
    id: String,
    name: String,
    #[serde(default)]
    category: String,
    #[serde(default)]
    blurb: String,
    #[serde(default)]
    auth: String,
}

/// How an app connects, from its snapshot auth type. The contract has no
/// "none" way; a no-auth app still goes through the connector's connect
/// flow, so it is `oauth` like the rest of the connector apps.
fn app_ways(auth: &str) -> Vec<&'static str> {
    match auth {
        "api_key" | "custom_credential" => vec!["paste"],
        _ => vec!["oauth"],
    }
}

fn item(entry: Entry) -> Item {
    let group_rank = GROUPS.iter().position(|g| *g == entry.group).unwrap_or(GROUPS.len());
    let name_lc = entry.name.to_lowercase();
    let other_lc = format!("{}\n{}", entry.category, entry.blurb).to_lowercase();
    Item { entry, group_rank, name_lc, other_lc }
}

/// The key rows that are brains: `KEY_ROWS` minus the ones clients already
/// draw as base rows (the voice keys `openai-voice` and `elevenlabs`).
fn brain_key_rows() -> impl Iterator<Item = &'static (&'static str, &'static str)> {
    KEY_ROWS.iter().filter(|(id, _)| !BASE_IDS.contains(id))
}

/// How many brains the catalog lists.
pub fn brain_key_count() -> usize {
    brain_key_rows().count()
}

fn build_items(snapshot: &str) -> Vec<Item> {
    let mut items: Vec<Item> = brain_key_rows()
        .map(|(id, _)| {
            item(Entry {
                id: (*id).to_string(),
                group: "brains",
                name: format!("{} key", key_row_name(id)),
                blurb: "Your own API key".to_string(),
                category: "API key".to_string(),
                ways: vec!["paste"],
                runs_on: "server",
                connector_id: None,
                key_page: Some(key_page(id)),
                logo: None,
                available: true,
                unavailable_reason: None,
                fallbacks: Vec::new(),
            })
        })
        .collect();

    let apps = match serde_json::from_str::<Snapshot>(snapshot) {
        Ok(snapshot) => snapshot.apps,
        Err(error) => {
            tracing::error!(%error, "connections catalog snapshot unreadable; listing no apps");
            Vec::new()
        }
    };
    let mut seen: HashSet<String> = items.iter().map(|i| i.entry.id.clone()).collect();
    for app in apps {
        let id = app.id.trim().to_string();
        if id.is_empty() || BASE_IDS.contains(&id.as_str()) || !seen.insert(id.clone()) {
            continue;
        }
        let category = app.category.trim().to_string();
        let blurb = match app.blurb.trim() {
            "" => category.clone(),
            blurb => blurb.to_string(),
        };
        items.push(item(Entry {
            connector_id: Some(id.clone()),
            id,
            group: "apps",
            name: app.name.trim().to_string(),
            blurb,
            category,
            ways: app_ways(app.auth.trim()),
            runs_on: "computer",
            key_page: None,
            logo: None,
            // Set per request (see `page`).
            available: false,
            unavailable_reason: Some(NEEDS_COMPUTER),
            fallbacks: vec!["this-mac"],
        }));
    }
    // Group order, then name: the order of a page with no `q`.
    items.sort_by(|a, b| (a.group_rank, &a.name_lc, &a.entry.id).cmp(&(b.group_rank, &b.name_lc, &b.entry.id)));
    items
}

fn items() -> &'static [Item] {
    static ITEMS: OnceLock<Vec<Item>> = OnceLock::new();
    ITEMS.get_or_init(|| build_items(SNAPSHOT))
}

/// 0 = name starts with `q`, 1 = name contains it, 2 = category or blurb
/// contains it, `None` = no match. No `q` matches everything at rank 0.
fn rank(item: &Item, q: Option<&str>) -> Option<u8> {
    let Some(q) = q else { return Some(0) };
    if item.name_lc.starts_with(q) {
        Some(0)
    } else if item.name_lc.contains(q) {
        Some(1)
    } else if item.other_lc.contains(q) {
        Some(2)
    } else {
        None
    }
}

/// One page of the catalog. `computer_online` decides `available` for apps.
pub fn page(query: &Query, computer_online: bool) -> Page {
    page_of(items(), query, computer_online)
}

fn page_of(items: &[Item], query: &Query, computer_online: bool) -> Page {
    let q = query.q.as_deref();
    let mut counts = Counts::default();
    // `items` is already in group, name order; a stable sort by rank keeps
    // ties by name.
    let mut matched: Vec<(usize, u8, &Item)> = Vec::new();
    for item in items {
        let Some(rank) = rank(item, q) else { continue };
        counts.bump(item.entry.group);
        if query.group.is_none_or(|group| group == item.entry.group) {
            matched.push((item.group_rank, rank, item));
        }
    }
    matched.sort_by_key(|(group_rank, rank, _)| (*group_rank, *rank));

    let total = matched.len();
    let start = query.offset.min(total);
    let end = start.saturating_add(query.limit).min(total);
    let entries = matched[start..end]
        .iter()
        .map(|(_, _, item)| {
            let mut entry = item.entry.clone();
            if entry.group == "apps" && computer_online {
                entry.available = true;
                entry.unavailable_reason = None;
                entry.fallbacks = Vec::new();
            }
            entry
        })
        .collect();
    let next_cursor = (query.limit > 0 && end < total).then(|| end.to_string());
    Page { version: VERSION, group: query.group, q: query.q.clone(), total, next_cursor, counts, entries }
}

/// Same env var and default as `connections::load_facts`.
const ENV_STALE_AFTER_SECS: &str = "ALLTERNIT_NODE_STALE_AFTER_SECS";

/// Whether the account has a computer online right now, by the same rule as
/// `connections::Facts::computer_online` in one query: an own computer
/// (relay-capable, not revoked, not a provisioned one) with a live relay
/// connection or a fresh `online` status, or a running paid/credit cloud
/// computer whose runtime holds a relay connection. `connected` = runtime
/// ids with a live relay connection.
pub async fn computer_online(
    db: &PgPool,
    user_id: &str,
    connected: &HashSet<String>,
    now: DateTime<Utc>,
) -> Result<bool, ApiError> {
    let stale_after = Duration::seconds(
        std::env::var(ENV_STALE_AFTER_SECS).ok().and_then(|v| v.parse::<i64>().ok()).unwrap_or(600),
    );
    let machines: Vec<(String, Option<String>, Option<DateTime<Utc>>, bool)> = sqlx::query_as(
        r#"
        SELECT d.id, d.status, d.last_seen_at, false AS cloud
        FROM runtime_devices d
        WHERE d.user_id = $1 AND d.revoked_at IS NULL
          AND d.capabilities LIKE '%"runtime:connect"%'
          AND d.runtime_type IN ('desktop', 'vps')
          AND NOT EXISTS (SELECT 1 FROM provisioned_instances i WHERE i.device_id = d.id)
        UNION ALL
        SELECT i.device_id, NULL::text, NULL::timestamptz, true AS cloud
        FROM provisioned_instances i
        WHERE i.user_id = $1 AND i.tier IN ('paid', 'credit') AND i.status = 'running'
          AND i.replaced_by IS NULL AND i.device_id IS NOT NULL
        "#,
    )
    .bind(user_id)
    .fetch_all(db)
    .await?;
    Ok(machines.iter().any(|(id, status, seen, cloud)| {
        connected.contains(id)
            || (!cloud && status.as_deref() == Some("online") && seen.is_some_and(|seen| now - seen <= stale_after))
    }))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn query(group: Option<&str>, q: Option<&str>, limit: Option<&str>, cursor: Option<&str>) -> Query {
        parse_query(group, q, limit, cursor).expect("valid query")
    }

    fn ids(page: &Page) -> Vec<&str> {
        page.entries.iter().map(|e| e.id.as_str()).collect()
    }

    /// A small catalog: the 11 key rows plus these apps.
    fn sample() -> Vec<Item> {
        build_items(
            r#"{"version":1,"generated_from":"test","apps":[
                {"id":"airtable","name":"Airtable","category":"Project management","blurb":"","auth":"composio"},
                {"id":"fairmarkit","name":"Fairmarkit","category":"Procurement","blurb":"","auth":"api_key"},
                {"id":"zapier","name":"Zapier","category":"Automation","blurb":"Hook up air conditioners","auth":"oauth2"},
                {"id":"aircall","name":"Aircall","category":"Phone","blurb":"Calls","auth":"custom_credential"},
                {"id":"hn","name":"Hacker News","category":"News","blurb":"","auth":"no_auth"},
                {"id":"gmail","name":"Gmail","category":"Email","blurb":"","auth":"composio"},
                {"id":"google_drive","name":"Google Drive","category":"Files","blurb":"","auth":"composio"},
                {"id":"slack","name":"Slack","category":"Chat","blurb":"","auth":"oauth2"},
                {"id":"discord","name":"Discord","category":"Chat","blurb":"","auth":"api_key"},
                {"id":"catalog","name":"Catalog","category":"Reserved","blurb":"","auth":"api_key"}
            ]}"#,
        )
    }

    #[test]
    fn catalog_snapshot_parses_and_leaves_out_base_rows() {
        let all = page(&query(None, None, Some("0"), None), false);
        assert_eq!(all.counts.brains, brain_key_count());
        assert_eq!(brain_key_count(), 11, "11 brain keys; the voice keys are base rows");
        assert!(all.counts.apps > 1_000, "snapshot has {} apps", all.counts.apps);
        assert_eq!(all.total, all.counts.brains + all.counts.apps);
        let every: Vec<String> = items().iter().map(|i| i.entry.id.clone()).collect();
        for base in ["gmail", "drive", "google_drive", "slack", "github", "notion", "discord", "telegram", "catalog", "openai-voice", "elevenlabs"] {
            assert!(!every.iter().any(|id| id == base), "{base} is a base row");
        }
        assert!(items().iter().all(|i| !i.entry.name.is_empty() && !i.entry.ways.is_empty()));
    }

    #[test]
    fn catalog_base_ids_absent() {
        let page = page_of(&sample(), &query(Some("apps"), None, Some("60"), None), false);
        assert_eq!(ids(&page), vec!["aircall", "airtable", "fairmarkit", "hn", "zapier"]);
    }

    #[test]
    fn catalog_entries_carry_the_contract_fields() {
        let items = sample();
        let page = page_of(&items, &query(Some("apps"), Some("airtable"), None, None), false);
        let entry = &page.entries[0];
        assert_eq!(entry.ways, vec!["oauth"]);
        assert_eq!(entry.connector_id.as_deref(), Some("airtable"));
        assert_eq!(entry.blurb, "Project management", "an empty blurb falls back to the category");
        assert_eq!((entry.available, entry.unavailable_reason), (false, Some(NEEDS_COMPUTER)));
        assert_eq!(entry.fallbacks, vec!["this-mac"]);
        let json = serde_json::to_value(&page).unwrap();
        for key in ["version", "group", "q", "total", "next_cursor", "counts", "entries"] {
            assert!(json.get(key).is_some(), "{key}");
        }
        for key in ["id", "group", "name", "blurb", "category", "ways", "runs_on", "connector_id", "key_page", "logo", "available", "unavailable_reason", "fallbacks"] {
            assert!(json["entries"][0].get(key).is_some(), "entry.{key}");
        }

        let online = page_of(&items, &query(Some("apps"), Some("airtable"), None, None), true);
        assert_eq!((online.entries[0].available, online.entries[0].unavailable_reason), (true, None));

        let paste = page_of(&items, &query(Some("apps"), Some("fairmarkit"), None, None), false);
        assert_eq!(paste.entries[0].ways, vec!["paste"]);
        let none = page_of(&items, &query(Some("apps"), Some("hacker"), None, None), false);
        assert_eq!(none.entries[0].ways, vec!["oauth"]);

        let brain = page_of(&items, &query(Some("brains"), Some("anthropic"), None, None), false);
        let entry = &brain.entries[0];
        assert_eq!((entry.id.as_str(), entry.name.as_str()), ("anthropic-key", "Anthropic key"));
        assert_eq!((entry.ways.clone(), entry.runs_on, entry.available), (vec!["paste"], "server", true));
        assert_eq!(entry.key_page, Some("https://console.anthropic.com/settings/keys"));
    }

    #[test]
    fn catalog_group_filter() {
        let items = sample();
        let brains = page_of(&items, &query(Some("brains"), None, Some("60"), None), false);
        assert_eq!(brains.group, Some("brains"));
        assert_eq!(brains.total, brain_key_count());
        assert!(brains.entries.iter().all(|e| e.group == "brains"));
        // Counts ignore the group.
        assert_eq!((brains.counts.brains, brains.counts.apps), (brain_key_count(), 5));

        let empty = page_of(&items, &query(Some("voice"), None, None, None), false);
        assert_eq!((empty.total, empty.entries.len(), empty.next_cursor.clone()), (0, 0, None));

        // No group: brains first, then apps.
        let all = page_of(&items, &query(None, None, Some("60"), None), false);
        assert_eq!(all.group, None);
        assert_eq!(all.total, brain_key_count() + 5);
        assert!(all.entries[..brain_key_count()].iter().all(|e| e.group == "brains"));
        assert!(all.entries[brain_key_count()..].iter().all(|e| e.group == "apps"));
    }

    #[test]
    fn catalog_q_ranking_order() {
        let items = sample();
        let page = page_of(&items, &query(None, Some("  AIR "), Some("60"), None), false);
        assert_eq!(page.q.as_deref(), Some("air"));
        // Starts with (by name), then contains (Fairmarkit), then blurb (Zapier).
        assert_eq!(ids(&page), vec!["aircall", "airtable", "fairmarkit", "zapier"]);
        assert_eq!((page.counts.apps, page.counts.brains, page.total), (4, 0, 4));

        // Category-only matches tie by name.
        let page = page_of(&items, &query(Some("apps"), Some("pro"), Some("60"), None), false);
        assert_eq!(ids(&page), vec!["airtable", "fairmarkit"]);

        // An empty q is no q.
        assert_eq!(query(None, Some("   "), None, None).q, None);
        // Cut to 64 characters.
        assert_eq!(query(None, Some("x".repeat(100).as_str()), None, None).q.unwrap().chars().count(), MAX_QUERY_CHARS);
    }

    #[test]
    fn catalog_limit_clamp_and_counts_only() {
        assert_eq!(query(None, None, Some("100"), None).limit, MAX_LIMIT);
        assert_eq!(query(None, None, Some("-3"), None).limit, 0);
        assert_eq!(query(None, None, None, None).limit, DEFAULT_LIMIT);
        assert_eq!(query(None, None, Some("abc"), None).limit, DEFAULT_LIMIT);

        let counts_only = page_of(&sample(), &query(None, None, Some("0"), None), false);
        assert!(counts_only.entries.is_empty());
        assert_eq!(counts_only.next_cursor, None);
        assert_eq!(counts_only.total, brain_key_count() + 5);
        assert_eq!((counts_only.counts.brains, counts_only.counts.apps, counts_only.counts.channels), (brain_key_count(), 5, 0));
        assert!(!needs_computer_fact(&query(None, None, Some("0"), None)));
        assert!(!needs_computer_fact(&query(Some("brains"), None, None, None)));
        assert!(needs_computer_fact(&query(Some("apps"), None, None, None)));

        let full = page(&query(Some("apps"), None, Some("100"), None), false);
        assert_eq!(full.entries.len(), MAX_LIMIT);
    }

    #[test]
    fn catalog_cursor_paging() {
        let items = sample();
        let first = page_of(&items, &query(None, None, Some("10"), None), false);
        assert_eq!(first.entries.len(), 10);
        assert_eq!(first.next_cursor.as_deref(), Some("10"));
        let second = page_of(&items, &query(None, None, Some("10"), first.next_cursor.as_deref()), false);
        assert_eq!(second.entries.len(), brain_key_count() + 5 - 10);
        assert_eq!(second.next_cursor, None);
        assert!(first.entries.iter().all(|a| second.entries.iter().all(|b| a.id != b.id)));
        // Past the end is an empty page, not an error.
        let past = page_of(&items, &query(None, None, None, Some("999")), false);
        assert_eq!((past.entries.len(), past.next_cursor.clone()), (0, None));
    }

    #[test]
    fn catalog_bad_group_and_cursor() {
        assert_eq!(parse_query(Some("gadgets"), None, None, None), Err(QueryError::UnknownGroup));
        assert_eq!(parse_query(None, None, None, Some("abc")), Err(QueryError::BadCursor));
        assert_eq!(parse_query(None, None, None, Some("-1")), Err(QueryError::BadCursor));
        assert_eq!(parse_query(None, None, None, Some("99999999999999999999999")), Err(QueryError::BadCursor));
        assert_eq!(QueryError::UnknownGroup.code(), "unknown_group");
        assert_eq!(QueryError::BadCursor.code(), "bad_cursor");
        assert_eq!(query(Some(""), None, None, Some("")), Query { group: None, q: None, limit: DEFAULT_LIMIT, offset: 0 });
    }
}
